/** A stable 100-fixture specification, not 100 copies of a hand.
 * Concrete hands and authoritative answers are regenerated by legacy Exercise v3. */
export const ACADEMY_QUESTION_VERSION='1.0.0';
const tasks=['discard','tenpai','multi_wait','discard','tenpai'];
export const BANK_SPEC=Object.freeze(Array.from({length:100},(_,i)=>{
  const level=Math.floor(i/20)+1;
  const lessonNumber=Math.floor(i/5)+1;
  const questionId='academy-q-'+String(i+1).padStart(3,'0');
  return Object.freeze({
    questionId,questionVersion:ACADEMY_QUESTION_VERSION,
    lessonId:'academy-l'+level+'-'+String((lessonNumber-1)%4+1).padStart(2,'0'),
    level,taskType:tasks[i%5],
    seed:'academy-v1-structural-'+String(i+1).padStart(4,'0'),
    index:i,legacyLevel:level===1?'beginner':level===2?'intermediate':'advanced'
  });
}));
export const QUESTION_REFS=Object.freeze(BANK_SPEC.map(({questionId,questionVersion})=>
  Object.freeze({questionId,questionVersion})));
export const getQuestionSpec=(id)=>BANK_SPEC.find(s=>s.questionId===id)??null;
